CREATE TABLE operators(id VARCHAR(40) PRIMARY KEY,name VARCHAR(100) NOT NULL,department VARCHAR(40) NOT NULL);
CREATE TABLE assets(id VARCHAR(40) PRIMARY KEY,name VARCHAR(100) NOT NULL,kind VARCHAR(20) NOT NULL,system_id VARCHAR(40) REFERENCES assets(id),owner_id VARCHAR(40) NOT NULL REFERENCES operators(id),criticality VARCHAR(20) NOT NULL);
CREATE TABLE dependencies(source_id VARCHAR(40) NOT NULL REFERENCES assets(id),target_id VARCHAR(40) NOT NULL REFERENCES assets(id),PRIMARY KEY(source_id,target_id),CHECK(source_id<>target_id));
CREATE TABLE scenarios(id VARCHAR(40) PRIMARY KEY,asset_id VARCHAR(40) NOT NULL REFERENCES assets(id),title VARCHAR(200) NOT NULL,observations TEXT NOT NULL,expected_type VARCHAR(30) NOT NULL,expected_severity VARCHAR(10) NOT NULL,expected_department VARCHAR(40) NOT NULL,expected_recurrence BOOLEAN NOT NULL);
CREATE TABLE incidents(id VARCHAR(40) PRIMARY KEY,title VARCHAR(200) NOT NULL,asset_id VARCHAR(40) NOT NULL REFERENCES assets(id),scenario_id VARCHAR(40) REFERENCES scenarios(id),owner_id VARCHAR(40) NOT NULL REFERENCES operators(id),type VARCHAR(30) NOT NULL,severity VARCHAR(10) NOT NULL,status VARCHAR(30) NOT NULL,mode VARCHAR(10) NOT NULL,provider VARCHAR(20) NOT NULL,observations TEXT NOT NULL,decision_json TEXT,impact_json TEXT,report_json TEXT,notes TEXT NOT NULL DEFAULT '',prevention TEXT NOT NULL DEFAULT '',created_at TIMESTAMP NOT NULL,resolved_at TIMESTAMP,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id VARCHAR(40) NOT NULL REFERENCES incidents(id),stage VARCHAR(40) NOT NULL,state VARCHAR(30) NOT NULL,message TEXT NOT NULL,data_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL);
CREATE INDEX events_incident ON events(incident_id,id);
CREATE INDEX incidents_created ON incidents(created_at);
CREATE TABLE audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id VARCHAR(40) REFERENCES incidents(id),actor VARCHAR(60) NOT NULL,action VARCHAR(80) NOT NULL,data_json TEXT NOT NULL,created_at TIMESTAMP NOT NULL);
CREATE TABLE approvals(incident_id VARCHAR(40) PRIMARY KEY REFERENCES incidents(id),approved BOOLEAN NOT NULL,actor VARCHAR(60) NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMP NOT NULL);
CREATE TABLE agent_tasks(id VARCHAR(80) PRIMARY KEY,agent VARCHAR(20) NOT NULL,incident_id VARCHAR(40) NOT NULL REFERENCES incidents(id),message_id VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,request_json TEXT NOT NULL,result_json TEXT,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,UNIQUE(agent,message_id));
CREATE TABLE manuals(id VARCHAR(40) PRIMARY KEY,type VARCHAR(30) NOT NULL,title VARCHAR(200) NOT NULL,procedure_text TEXT NOT NULL);
CREATE TABLE skills(id VARCHAR(40) PRIMARY KEY,type VARCHAR(30) NOT NULL,title VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL,conditions TEXT NOT NULL,checks TEXT NOT NULL,solution TEXT NOT NULL,cautions TEXT NOT NULL,incident_id VARCHAR(40) REFERENCES incidents(id),approved_by VARCHAR(60),created_at TIMESTAMP NOT NULL);
CREATE TABLE simulated_metrics(incident_id VARCHAR(40) PRIMARY KEY REFERENCES incidents(id),before_json TEXT NOT NULL,current_json TEXT NOT NULL,applied BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE evaluations(id VARCHAR(40) PRIMARY KEY,mode VARCHAR(10) NOT NULL,provider VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,result_json TEXT,created_at TIMESTAMP NOT NULL);
